        int il = Initial.InGetIi(ii, r, 2);
        int jn = Initial.InGetIi(ii, r, 10);
        int w = Initial.InGetIi(ii, r, 9);
        int j = 0;
        if (il >= 0) {
            int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
            // (the initial's text: `ncp` code points of the word, all of it when it has a line of its own)
            while (j < Initial.InGetIi(ii, r, 4)) {
                emon.Port.CellsPush(raw, emon.Port.CellsAt(et, ts + j));
                j += 1;
            }
            if (jn == 2) {
                emon.Port.CellsPush(raw, 32);
            }
        }
        emon.Port.CellsSet(fr, @base + FrNcp, Initial.InGetIi(ii, r, 4));
        emon.Port.CellsSet(fr, @base + FrForm, Initial.InGetIi(ii, r, 0));
        emon.Port.CellsSet(fr, @base + FrLines, Initial.InGetIi(ii, r, 1));
        if (jn == 1) {
            emon.Port.CellsSet(fr, @base + FrFlag, 1);
        }
        if (Initial.InGetIi(ii, r, 5) < emon.Port.CellsAt(fr, @base + 1)) {
            emon.Port.CellsSet(fr, @base + 1, Initial.InGetIi(ii, r, 5));
        }
        if (Initial.InGetIi(ii, r, 6) < emon.Port.CellsAt(fr, @base + 2)) {
            emon.Port.CellsSet(fr, @base + 2, Initial.InGetIi(ii, r, 6));
        }
        if (Initial.InGetIi(ii, r, 7) > emon.Port.CellsAt(fr, @base + 3)) {
            emon.Port.CellsSet(fr, @base + 3, Initial.InGetIi(ii, r, 7));
        }
        if (Initial.InGetIi(ii, r, 8) > emon.Port.CellsAt(fr, @base + 4)) {
            emon.Port.CellsSet(fr, @base + 4, Initial.InGetIi(ii, r, 8));
        }
        return 1;
    }
    internal static int PaCl(int v) {
        if (v > PaBig) {
            return PaBig;
        }
        if (v < (0 - PaBig)) {
            return 0 - PaBig;
        }
        return v;
    }
    internal static int PaAlAdd(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells al, int l, int fx0, int fx1) {
        // One line of the open paragraph for the alignment test (P4.11, SPEC 10.10): its start and end gaps against the box
        // [fx0, fx1] of the fragment it sits in, each from the line's own side, and its size.
        int x0 = PaCl(Evidence.LnGet(ln, l, Evidence.LhX0()));
        int x1 = PaCl(Evidence.LnGet(ln, l, Evidence.LhX1()));
        int b0 = PaCl(fx0);
        int b1 = PaCl(fx1);
        if (Evidence.LnGet(ln, l, Evidence.LhDir()) == 1) {
            Align.AlLine(al, b1 - x1, x0 - b0, PaSize(wd, ln, l), PaStyle(wd, ln, l));
        } else {
            Align.AlLine(al, x0 - b0, b1 - x1, PaSize(wd, ln, l), PaStyle(wd, ln, l));
        }
        return 0;
    }
    internal static int PaFragExtend(emon.Port.Cells fr, emon.Port.Cells ln, int l) {
        // The last fragment takes in the line's box.
        int @base = ((emon.Port.CellsLen(fr) / FrStride) - 1) * FrStride;
        int ox0 = emon.Port.CellsAt(fr, @base + 1);
        int oy0 = emon.Port.CellsAt(fr, @base + 2);
        int ox1 = emon.Port.CellsAt(fr, @base + 3);
        int oy1 = emon.Port.CellsAt(fr, @base + 4);
        int lx0 = Evidence.LnGet(ln, l, Evidence.LhX0());
        int ly0 = Evidence.LnGet(ln, l, Evidence.LhY0());
        int lx1 = Evidence.LnGet(ln, l, Evidence.LhX1());
        int ly1 = Evidence.LnGet(ln, l, Evidence.LhY1());
        if (lx0 < ox0) {
            emon.Port.CellsSet(fr, @base + 1, lx0);
        }
        if (ly0 < oy0) {
            emon.Port.CellsSet(fr, @base + 2, ly0);
        }
        if (lx1 > ox1) {
            emon.Port.CellsSet(fr, @base + 3, lx1);
        }
        if (ly1 > oy1) {
            emon.Port.CellsSet(fr, @base + 4, ly1);
        }
        return 0;
    }
    internal static int PaHeadingNumber(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, int par, int from, int to, emon.Port.Cells hc, int hl) {
        // A numbered heading (D167): the number goes to the `number` attribute and its scheme to `numbering`,
        // and the text starts after them. Answers how many code points of `raw` the title is further on (0: the
        // line is kept whole).
        int skip = Heading.HdField(hc, hl, Heading.HckSkip());
        int ns = Heading.HdField(hc, hl, Heading.HckNstart());
        int nl = Heading.HdField(hc, hl, Heading.HckNlen());
        if ((skip <= 0) || ((from + skip) >= to)) {
            return 0;
        }
        if ((nl < 1) || ((ns + nl) > skip)) {
            return 0;
        }
        int t0 = emon.Port.CellsLen(text);
        Normalize.NzNfc(raw, from + ns, (from + ns) + nl, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
        Model.NodeSetAttrText(nodes, attrs, par, Model.FkNumber(), t0, emon.Port.CellsLen(text) - t0);
        int t1 = emon.Port.CellsLen(text);
        int n = Heading.HdPutScheme(text, Heading.HdField(hc, hl, Heading.HckScheme()));
        Model.NodeSetAttrText(nodes, attrs, par, Model.FkNumbering(), t1, n);
        return skip;
    }
    internal static int PaGroupEnd(emon.Port.Cells raw, int s, int rawn) {
        // The index one past the END of the group that opens at `s` (an opener of `emon.lists`), or -1 when the
        // group is not closed before `rawn`.
        int i = s + 1;
        while (i < rawn) {
            if (emon.Port.CellsAt(raw, i) == Lists.LsSEnd()) {
                return i + 1;
            }
            i += 1;
        }
        return -1;
    }
    internal static int PaGroupSep(emon.Port.Cells raw, int s, int gend) {
        // The index of the separator of the group at `s`..`gend`, which ends its header and starts its text.
        int i = s + 1;
        while (i < gend) {
            if (emon.Port.CellsAt(raw, i) == Lists.LsSSep()) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int PaGroupValue(emon.Port.Cells raw, int s, int sep) {
        // The number the header of the group holds (the digits after the code cell); 0 when it holds none.
        int i = s + 2;
        int v = 0;
        while (i < sep) {
            v = (v * 10) + (emon.Port.CellsAt(raw, i) - 48);
            i += 1;
        }
        return v;
    }
    internal static int PaPutMarker(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells raw, int node, int key, int from, int to) {
        // The code points raw[from..to) as the text attribute `key` of the node (a marker, a label).
        int t0 = emon.Port.CellsLen(text);
        int i = from;
        while (i < to) {
            Model.TextAppendCp(text, emon.Port.CellsAt(raw, i));
            i += 1;
        }
        Model.NodeSetAttrText(nodes, attrs, node, key, t0, to - from);
        return 0;
    }
    internal static int PaCut(emon.Port.Cells raw, emon.Port.Cells fr, int a, int b) {
        // Remove raw[a..b), moving what follows down, and move the raw starts of the fragments (`fr`, cell 5 of a row)
        // that lie beyond a.
        int n = emon.Port.CellsLen(raw);
        int d = b - a;
        int j = a;
        int k = 0;
        while ((j + d) < n) {
            emon.Port.CellsSet(raw, j, emon.Port.CellsAt(raw, j + d));
            j += 1;
        }
        emon.Port.CellsDrop(raw, n - d);
        while (k < (emon.Port.CellsLen(fr) / FrStride)) {
            int s = emon.Port.CellsAt(fr, (k * FrStride) + 5);
            if (s >= b) {
                emon.Port.CellsSet(fr, (k * FrStride) + 5, s - d);
            }
            if ((s > a) && (s < b)) {
                emon.Port.CellsSet(fr, (k * FrStride) + 5, a);
            }
            k += 1;
        }
        return 0;
    }
    internal static int PaScrub(emon.Port.Cells raw, emon.Port.Cells fr, int from) {
        // Cut every list, note or caption group at or after `from`: the stages leave one only at a paragraph's start.
        int i = from;
        while (i < emon.Port.CellsLen(raw)) {
            int c = emon.Port.CellsAt(raw, i);
            int n = emon.Port.CellsLen(raw);
            if ((c == Lists.LsSItem()) || ((c == Lists.LsSNote()) || (c == Lists.LsSCap()))) {
                int gend = PaGroupEnd(raw, i, n);
                if (gend > 0) {
                    if ((gend < n) && (emon.Port.CellsAt(raw, gend) == 32)) {
                        PaCut(raw, fr, i, gend + 1);
                    } else {
                        PaCut(raw, fr, i, gend);
                    }
                } else {
                    i += 1;
                }
            } else {
                i += 1;
            }
        }
        return 0;
    }
    internal static int PaHasRef(emon.Port.Cells raw, int from, int to) {
        // 1 when the range holds a note reference group.
        int i = from;
        while (i < to) {
            if (emon.Port.CellsAt(raw, i) == Lists.LsSRef()) {
                return 1;
            }
            i += 1;
        }
        return 0;
    }
    internal static int PaTextChild(emon.Port.Cells nodes, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, int par, int from, int to) {
        // A `text` inline of the paragraph for raw[from..to), normalised. Answers its node.
        int child = Model.NodeNew(nodes, Model.NkText(), par);
        int t0 = emon.Port.CellsLen(text);
        Normalize.NzNfc(raw, from, to, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
        Model.NodeSetText(nodes, child, t0, emon.Port.CellsLen(text) - t0);
        Model.NodeSetConf(nodes, child, 1000);
        Model.NodeAddSrc(nodes, child, Model.SrText());
        return child;
    }
    internal static int PaInlines(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, int par, int from, int to) {
        // The inline children of the paragraph for raw[from..to): `text` runs, and a `ref` for every note reference
        // group (its marker; the target is set later, when the notes are known). A space before a reference is not
        // text: the reference stands where the marker was printed, against the word. Answers the first `text` child, -1
        // when there is none.
        int i = from;
        int seg = from;
        int first = -1;
        int child = 0;
        while (i < to) {
            if (emon.Port.CellsAt(raw, i) == Lists.LsSRef()) {
                int gend = PaGroupEnd(raw, i, to);
                int sep = PaGroupSep(raw, i, gend);
                if ((gend < 0) || (sep < 0)) {
                    i += 1;
                } else {
                    int se = i;
                    if ((se > seg) && (emon.Port.CellsAt(raw, se - 1) == 32)) {
                        se -= 1;
                    }
                    if (se > seg) {
                        child = PaTextChild(nodes, text, raw, tmp, par, seg, se);
                        if (first < 0) {
                            first = child;
                        }
                    }
                    child = Model.NodeNew(nodes, Model.NkRef(), par);
                    Model.NodeSetConf(nodes, child, 500);
                    Model.NodeAddSrc(nodes, child, Model.SrText());
                    Model.NodeAddSrc(nodes, child, Model.SrInfer());
                    PaPutMarker(nodes, attrs, text, raw, child, Model.FkMarker(), sep + 1, gend - 1);
                    i = gend;
                    seg = gend;
                }
            } else {
                i += 1;
            }
        }
        if (seg < to) {
            child = PaTextChild(nodes, text, raw, tmp, par, seg, to);
            if (first < 0) {
                first = child;
            }
        }
        return first;
    }
    internal static int PaFlush(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells al, emon.Port.Cells hc, int parent) {
        // Close the open paragraph, if there is one, under `parent`: its node, `at` one region per fragment (a
        // column or a page), `src`, `conf`. The text is the paragraph's own when it is on one page, else a `text`
        // inline per page it is on with a `break` milestone between two, a column break being only a new region
        // (SPEC 10.1.2). Under the root (parent 0) a paragraph the heading analysis found a heading in is a `heading` of its
        // level under the open section it belongs in (D167). A paragraph that an initial opens (`fr`'s first row, P4.10) has an
        // `initial` inline first, holding the initial's text, and the rest of its text as a `text` inline (also when it is on one
        // page, where it has its own `text` as well, equal to the two); no list, note or caption group is read there (the
        // initial wins, D229). A paragraph that starts with a group of the list, note or caption stage is an `item`, a `note`
        // holding a paragraph, or a `caption` (D179), the group's marker or label an attribute and not in the text; note
        // reference groups in the text become `ref` inlines. Closes the block's line rows in `al` (P4.11: `al-mark`,
        // `al-pass` decides at the end). Empties `raw` and `fr`.
        int nfr = emon.Port.CellsLen(fr) / FrStride;
        int rawn = emon.Port.CellsLen(raw);
        if (nfr == 0) {
            emon.Port.CellsDrop(raw, 0);
            return 0;
        }
        int hl = emon.Port.CellsAt(fr, 6);
        int ncp = emon.Port.CellsAt(fr, FrNcp);
        int lev = 0;
        int sect = parent;
        int kind = Model.NkParagraph();
        int par = 0;
        int own = -1;
        int lead = 0;
        int gcode = 0;
        int gval = 0;
        int gm0 = 0;
        int gm1 = 0;
        int blk = 0;
        int k = 0;
        int kend = 0;
        int runs = 1;
        int from = 0;
        int to = 0;
        int cut = 0;
        int ini = 0;
        int t0 = 0;
        int child = 0;
        int kids = 0;
        if (parent == 0) {
            lev = Heading.HdLevel(hc, hl);
            sect = Heading.HdParent(hc, nodes, lev);
        }
        // a group at the start of the paragraph: an item, a note body or a caption (not inside a margin note)
        if ((lev == 0) && ((rawn > 0) && (ncp == 0))) {
            int c0 = emon.Port.CellsAt(raw, emon.Port.CellsAt(fr, 5));
            int s0 = emon.Port.CellsAt(fr, 5);
            if ((c0 == Lists.LsSItem()) || ((c0 == Lists.LsSNote()) || (c0 == Lists.LsSCap()))) {
                int gend = PaGroupEnd(raw, s0, rawn);
                int sep = PaGroupSep(raw, s0, gend);
                if ((gend > 0) && (sep > 0) && ((parent == 0) || (Model.NodeKind(nodes, parent) != Model.NkNote()))) {
                    gcode = emon.Port.CellsAt(raw, s0 + 1) - Lists.LsSBase();
                    gval = PaGroupValue(raw, s0, sep);
                    gm0 = sep + 1;
                    gm1 = gend - 1;
                    lead = gend - s0;
                    if ((gend < rawn) && (emon.Port.CellsAt(raw, gend) == 32)) {
                        lead += 1;
                    }
                    if (c0 == Lists.LsSItem()) {
                        blk = 1;
                    }
                    if (c0 == Lists.LsSNote()) {
                        blk = 2;
                    }
                    if (c0 == Lists.LsSCap()) {
                        blk = 3;
                    }
                } else {
                    // an unusable group (inside a margin note, or not closed): its text is dropped, the rest kept
                    if (gend > 0) {
                        lead = gend - s0;
                        if ((gend < rawn) && (emon.Port.CellsAt(raw, gend) == 32)) {
                            lead += 1;
                        }
                    }
                }
            }
        }
        // a group that is still in the text after the first is a stray (the stages put one only at a line's start, and
        // a paragraph's first line is its start): it is cut out, with its space
        PaScrub(raw, fr, emon.Port.CellsAt(fr, 5) + lead);
        rawn = emon.Port.CellsLen(raw);
        if (lev > 0) {
            kind = Model.NkHeading();
        }
        if (blk == 1) {
            kind = Model.NkItem();
        }
        if (blk == 3) {
            kind = Model.NkCaption();
        }
        if (blk == 2) {
            own = Model.NodeNew(nodes, Model.NkNote(), sect);
            sect = own;
        }
        par = Model.NodeNew(nodes, kind, sect);
        if (lev > 0) {
            Model.NodeSetSub(nodes, par, lev);
        }
        Model.NodeSetConf(nodes, par, 500);
        Model.NodeAddSrc(nodes, par, Model.SrText());
        Model.NodeAddSrc(nodes, par, Model.SrInfer());
        if (blk == 1) {
            Model.NodeSetSub(nodes, par, gcode);
            Model.NodeSetAux(nodes, par, gval);
            Model.NodeSetAttrInt(nodes, attrs, par, Model.FkBox(), Lists.LsGet(hc, hl, Lists.LsKTextx()));
            PaPutMarker(nodes, attrs, text, raw, par, Model.FkMarker(), gm0, gm1);
        }
        if (blk == 3) {
            Model.NodeSetAux(nodes, par, gcode);
            PaPutMarker(nodes, attrs, text, raw, par, Model.FkLabel(), gm0, gm1);
        }
        if (blk == 2) {
            Model.NodeSetSub(nodes, own, gcode);
            Model.NodeSetConf(nodes, own, 500);
            Model.NodeAddSrc(nodes, own, Model.SrInfer());
            PaPutMarker(nodes, attrs, text, raw, own, Model.FkMarker(), gm0, gm1);
        }
        k = 1;
        while (k < nfr) {
            if (emon.Port.CellsAt(fr, k * FrStride) != emon.Port.CellsAt(fr, (k - 1) * FrStride)) {
                runs += 1;
            }
            k += 1;
        }
        k = 0;
        while (k < nfr) {
            int pg = emon.Port.CellsAt(fr, k * FrStride);
            kend = k + 1;
            while ((kend < nfr) && (emon.Port.CellsAt(fr, kend * FrStride) == pg)) {
                kend += 1;
            }
            from = emon.Port.CellsAt(fr, (k * FrStride) + 5);
            if (k == 0) {
                from += lead;
            }
            to = rawn;
            if (kend < nfr) {
                to = emon.Port.CellsAt(fr, (kend * FrStride) + 5);
            }
            kids = 0;
            if (runs > 1) {
                kids = 1;
            }
            if ((k == 0) && (ncp > 0)) {
                kids = 1;
            }
            if (PaHasRef(raw, from, to) == 1) {
                kids = 1;
            }
            child = -1;
            if (kids == 1) {
                if ((runs > 1) && (k > 0)) {
                    int br = Model.NodeNew(nodes, Model.NkBreak(), par);
                    Model.NodeSetSub(nodes, br, pg);
                    Model.NodeSetConf(nodes, br, 500);
                    Model.NodeAddSrc(nodes, br, Model.SrInfer());
                }
                cut = from;
                if ((k == 0) && (ncp > 0)) {
                    cut = from + ncp;
                    if (cut > to) {
                        cut = to;
                    }
                    ini = Model.NodeNew(nodes, Model.NkInitial(), par);
                    Model.NodeSetSub(nodes, ini, emon.Port.CellsAt(fr, FrForm));
                    Model.NodeSetAux(nodes, ini, emon.Port.CellsAt(fr, FrLines));
                    Model.NodeSetConf(nodes, ini, 800);
                    if (emon.Port.CellsAt(fr, FrFlag) == 1) {
                        Model.NodeSetConf(nodes, ini, 500);
                        Model.NodeAddFlag(nodes, ini, Model.FlLowConf());
                    }
                    Model.NodeAddSrc(nodes, ini, Model.SrText());
                    Model.NodeAddSrc(nodes, ini, Model.SrInfer());
                    child = Model.NodeNew(nodes, Model.NkText(), ini);
                    t0 = emon.Port.CellsLen(text);
                    Normalize.NzNfc(raw, from, cut, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                    int tn0 = emon.Port.CellsLen(text) - t0;
                    Model.NodeSetText(nodes, child, t0, tn0);
                    Model.NodeSetConf(nodes, child, 1000);
                    Model.NodeAddSrc(nodes, child, Model.SrText());
                    child = -1;
                }
                if ((runs > 1) || (cut < to)) {
                    child = PaInlines(nodes, attrs, text, raw, tmp, par, cut, to);
                }
                if ((runs > 1) && (child < 0) && (k == 0) && (ncp > 0)) {
                    child = PaTextChild(nodes, text, raw, tmp, par, cut, to);
                }
                if ((runs == 1) && (PaHasRef(raw, from, to) == 0)) {
                    t0 = emon.Port.CellsLen(text);
                    Normalize.NzNfc(raw, from, to, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                    int tn1 = emon.Port.CellsLen(text) - t0;
                    Model.NodeSetText(nodes, par, t0, tn1);
                }
            } else {
                if (lev > 0) {
                    from += PaHeadingNumber(nodes, attrs, text, raw, tmp, par, from, to, hc, hl);
                }
                t0 = emon.Port.CellsLen(text);
                Normalize.NzNfc(raw, from, to, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                int tn2 = emon.Port.CellsLen(text) - t0;
                Model.NodeSetText(nodes, par, t0, tn2);
            }
            while (k < kend) {
                int @base = k * FrStride;
                int rx0 = emon.Port.CellsAt(fr, @base + 1);
                int ry0 = emon.Port.CellsAt(fr, @base + 2);
                int rx1 = emon.Port.CellsAt(fr, @base + 3);
                int ry1 = emon.Port.CellsAt(fr, @base + 4);
                Model.NodeAddRegion(nodes, regions, par, pg, rx0, ry0, rx1, ry1);
                if (own >= 0) {
                    Model.NodeAddRegion(nodes, regions, own, pg, rx0, ry0, rx1, ry1);
                }
                if ((runs > 1) && (child >= 0)) {
                    Model.NodeAddRegion(nodes, regions, child, pg, rx0, ry0, rx1, ry1);
                }
                k += 1;
            }
        }
        Align.AlMark(al, par);
        emon.Port.CellsDrop(raw, 0);
        emon.Port.CellsDrop(fr, 0);
        return 0;
    }
    internal static int PaMilestone(emon.Port.Cells nodes, int page, emon.Port.Cells hc) {
        // A page milestone between two blocks, in the open section when there is one (D167).
        int b = Model.NodeNew(nodes, Model.NkBreak(), Heading.HdCur(hc));
        Model.NodeSetSub(nodes, b, page);
        Model.NodeSetConf(nodes, b, 500);
        Model.NodeAddSrc(nodes, b, Model.SrInfer());
        return 0;
    }
    internal static bool PaLetter(int cp) {
        // A letter, for the hyphen at a break: Basic Latin, Latin-1, Greek, Cyrillic, and anything above U+2FF
        // that is not punctuation or a symbol (the CJK block and beyond).
        if ((cp >= 65) && (cp <= 90)) {
            return 1 == 1;
        }
        if (PaLower(cp)) {
            return 1 == 1;
        }
        if ((cp >= 192) && (cp <= 591)) {
            return 1 == 1;
        }
        if ((cp >= 880) && (cp <= 1327)) {
            return 1 == 1;
        }
        return 0 == 1;
    }
    internal static bool PaBullet(int cp) {
        // A bullet or a dash that stands alone as a word: a list marker.
        if ((cp == 8226) || (cp == 183) || (cp == 9679)) {
            return 1 == 1;
        }
        if ((cp == 9632) || (cp == 9642) || (cp == 8259)) {
            return 1 == 1;
        }
        if ((cp == 42) || (cp == 45) || (cp == 8211) || (cp == 8212)) {
            return 1 == 1;
        }
        return 0 == 1;
    }
    internal static bool PaMarker(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, int l) {
        // Does the line start with a list marker: a bullet or dash alone, `1.`, `12)`, `a)`, `(a)`.
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        int wn = Evidence.LnGet(ln, l, Evidence.LhCount());
        if (wn < 1) {
            return 0 == 1;
        }
        int ts = Evidence.WdGet(wd, w0, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w0, Evidence.HdTlen());
        if ((ts < 0) || (tl < 1)) {
            return 0 == 1;
        }
        int c0 = emon.Port.CellsAt(et, ts);
        if (tl == 1) {
            return PaBullet(c0);
        }
        if (tl > 5) {
            return 0 == 1;
        }
        int cl = emon.Port.CellsAt(et, ts + (tl - 1));
        if ((c0 >= 48) && (c0 <= 57)) {
            if ((cl != 46) && (cl != 41)) {
                return 0 == 1;
            }
            int k = 1;
            while (k < (tl - 1)) {
                int c = emon.Port.CellsAt(et, ts + k);
                if ((c < 48) || (c > 57)) {
                    return 0 == 1;
                }
                k += 1;
            }
            return 1 == 1;
        }
        if ((c0 == 40) && (cl == 41) && (tl == 3)) {
            return 1 == 1;
        }
        if ((tl == 2) && PaLetter(c0) && (cl == 41)) {
            return 1 == 1;
        }
        return 0 == 1;
    }
    internal static int PaBottom(emon.Port.Cells cf, int r) {
        // The bottom a fragment's last line is compared with: the bottom of the region its vertical cuts came from, so
        // the columns of one set (side by side, whatever else lies above or below beside them) end together.
        return emon.Port.CellsAt(cf, (r * CfStride) + CfRef);
    }
    internal static int PaMaxi(int a, int b) {
        if (a > b) {
            return a;
        }
        return b;
    }
    internal static int PaJoinScore(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells raw, int a, int b, int colx0, int colx1, int ncol, int bmargin, int indents, int bottom, int bx0, int bx1, int bn, emon.Port.Cells hc) {
        // The points for the paragraph that ended its fragment (its last line a, the text so far in `raw`) going
        // on with line b, the first of the next fragment (SPEC 10.1.2, D164). `colx0`..`colx1` is the extent of a's
        // fragment, `ncol` its lines (the edge signals need two), `bmargin` the margin of b's, `indents` whether
        // the document's paragraphs have first-line indents, `bottom` the bottom of the fragments of a's band.
        int n = emon.Port.CellsLen(raw);
