        int sb = PaSize(wd, ln, b);
        int pts = 0;
        if (n < 1) {
            return -100;
        }
        if ((Heading.HdLevel(hc, a) > 0) || (Heading.HdLevel(hc, b) > 0)) {
            return -100;
        }
        if (Lists.LsStart(hc, b) == 1) {
            return -100;
        }
        int last = emon.Port.CellsAt(raw, n - 1);
        if (((last == 45) || (last == 173)) && (n >= 2)) {
            if (PaLetter(emon.Port.CellsAt(raw, n - 2))) {
                pts += JsHyphen;
