            PaLayout(cf, r0, emon.Port.CellsLen(cf) / CfStride, p, pages, layout);
            p += 1;
        }
        return 0;
    }
    internal static int PaLive(emon.Port.Cells ln, emon.Port.Cells lo, int first, int cnt) {
